      await transaction.rollback();
      reply.code(404).send({ error: "Customer not found" });
      return;
    }

    await Order.destroy({
      where: { o_custkey: c_custkey },
      transaction,
    });

    await Customer.destroy({
      where: { c_custkey },
      transaction,
    });

    await transaction.commit();
    reply.code(204).send();
  } catch (err) {
    await transaction.rollback();
