			tx.Rollback()
			c.Status(http.StatusInternalServerError)
			return
		}
		if err := tx.Exec("DELETE FROM customer WHERE c_custkey = ?", c.Param("c_custkey")).Error; err != nil {
			tx.Rollback()
			c.Status(http.StatusInternalServerError)
			return
		}
		if err := tx.Commit().Error; err != nil {
