  {
    tableName: "product",
    timestamps: false,
    freezeTableName: true,
  }
);

app.put("/api/products/:p_productkey/price", async (req, res) => {
  const p_productkey = parseInt(req.params.p_productkey, 10);
  const payload = req.body || {};

