		})
	})

	port := getEnv("PORT", "5000")
	log.Fatal(app.Listen("0.0.0.0:" + port))
}

func nullStringToAny(ns sql.NullString) interface{} {
	if ns.Valid {
		return ns.String
	}
	return nil
}

