    ).fetchone()
    if existing is None:
        return JSONResponse({"error": "Supplier not found"}, status_code=404)
    db.execute(
        "UPDATE supplier SET s_status = 'suspended' WHERE s_suppkey = ?",
        (s_suppkey,),
