            payload["l_discount"],
            payload["l_tax"],
            o_orderkey,
            l_linenumber
        );

        db.prepare(
            "UPDATE orders SET o_totalprice = " +
            "(SELECT COALESCE(SUM(l_extendedprice * (1 - l_discount) * (1 + l_tax)), 0) " +
            " FROM lineitem WHERE l_orderkey = ?) " +
            "WHERE o_orderkey = ?"
