		if !ok {
			return c.Status(500).JSON(fiber.Map{"error": "missing l_discount"})
		}
		lTax, ok := toFloat64(payload["l_tax"])
		if !ok {
			return c.Status(500).JSON(fiber.Map{"error": "missing l_tax"})
		}

