				oOrderkey, lLinenumber, lExtendedprice, lDiscount, lTax, lShipdate, lComment,
			)
			if res.Error != nil {
				tx.Rollback()
				c.JSON(http.StatusInternalServerError, gin.H{"error": res.Error.Error()})
				return
			}
		}

