package main

import (
	"errors"
	"log"
	"os"
	"strconv"

	"github.com/gofiber/fiber/v2"
	"gorm.io/driver/sqlite"
	"gorm.io/gorm"
)

type Order struct {
	OOrderkey    int     `gorm:"column:o_orderkey;primaryKey;autoIncrement" json:"o_orderkey"`
	OOrderstatus string  `gorm:"column:o_orderstatus" json:"o_orderstatus"`
	OTotalprice  float64 `gorm:"column:o_totalprice" json:"o_totalprice"`
	OOrderdate   string  `gorm:"column:o_orderdate" json:"o_orderdate"`
	OComment     string  `gorm:"column:o_comment" json:"o_comment"`
}

func (Order) TableName() string {
	return "orders"
}

type Lineitem struct {
	LOrderkey      int      `gorm:"column:l_orderkey;primaryKey" json:"l_orderkey"`
	LLinenumber    int      `gorm:"column:l_linenumber;primaryKey" json:"l_linenumber"`
	LExtendedprice float64  `gorm:"column:l_extendedprice" json:"l_extendedprice"`
	LDiscount      float64  `gorm:"column:l_discount" json:"l_discount"`
	LTax           float64  `gorm:"column:l_tax" json:"l_tax"`
	LShipdate      *string  `gorm:"column:l_shipdate" json:"l_shipdate"`
	LComment       string   `gorm:"column:l_comment" json:"l_comment"`
}

func (Lineitem) TableName() string {
	return "lineitem"
}

type CreateOrderLineitemPayload struct {
	LLinenumber    int      `json:"l_linenumber"`
	LExtendedprice float64  `json:"l_extendedprice"`
	LDiscount      float64  `json:"l_discount"`
	LTax           float64  `json:"l_tax"`
	LShipdate      *string  `json:"l_shipdate"`
	LComment       *string  `json:"l_comment"`
}

type CreateOrderPayload struct {
	OOrderstatus *string                      `json:"o_orderstatus"`
	OOrderdate   string                       `json:"o_orderdate"`
	OComment     *string                      `json:"o_comment"`
	Lineitems    []CreateOrderLineitemPayload `json:"lineitems"`
}

type AddLineitemPayload struct {
	LLinenumber    int      `json:"l_linenumber"`
	LExtendedprice float64  `json:"l_extendedprice"`
	LDiscount      float64  `json:"l_discount"`
	LTax           float64  `json:"l_tax"`
	LShipdate      *string  `json:"l_shipdate"`
	LComment       *string  `json:"l_comment"`
}

func main() {
	database := os.Getenv("DB_PATH")
	if database == "" {
		database = "app.db"
	}

	db, err := gorm.Open(sqlite.Open(database), &gorm.Config{})
	if err != nil {
		log.Fatal(err)
	}

	sqlDB, err := db.DB()
	if err != nil {
		log.Fatal(err)
	}
	defer sqlDB.Close()

	app := fiber.New()

	app.Get("/api/orders/:o_orderkey<int>", func(c *fiber.Ctx) error {
		oOrderkey, err := strconv.Atoi(c.Params("o_orderkey"))
		if err != nil {
			return c.Status(404).JSON(fiber.Map{"error": "Order not found"})
		}

		var row Order
		result := db.Select("o_orderkey, o_orderstatus, o_totalprice, o_orderdate, o_comment").
			Where("o_orderkey = ?", oOrderkey).
			First(&row)

		if errors.Is(result.Error, gorm.ErrRecordNotFound) {
			return c.Status(404).JSON(fiber.Map{"error": "Order not found"})
		}
		if result.Error != nil {
			return result.Error
		}

		return c.Status(200).JSON(fiber.Map{
			"o_orderkey":    row.OOrderkey,
			"o_orderstatus": row.OOrderstatus,
			"o_totalprice":  row.OTotalprice,
			"o_orderdate":   row.OOrderdate,
			"o_comment":     row.OComment,
		})
	})

	app.Post("/api/orders/:o_orderkey<int>/lineitems", func(c *fiber.Ctx) error {
		payload := AddLineitemPayload{}
		if err := c.BodyParser(&payload); err != nil {
			payload = AddLineitemPayload{}
		}

		oOrderkey, err := strconv.Atoi(c.Params("o_orderkey"))
		if err != nil {
			return c.Status(404).JSON(fiber.Map{"error": "Order not found"})
		}

		tx := db.Begin()
		if tx.Error != nil {
			return tx.Error
		}

		var order struct {
			OOrderkey int `gorm:"column:o_orderkey"`
		}
		result := tx.Table("orders").Select("o_orderkey").Where("o_orderkey = ?", oOrderkey).Take(&order)
		if errors.Is(result.Error, gorm.ErrRecordNotFound) {
			tx.Rollback()
			return c.Status(404).JSON(fiber.Map{"error": "Order not found"})
		}
		if result.Error != nil {
			tx.Rollback()
			return result.Error
		}

		comment := ""
		if payload.LComment != nil {
			comment = *payload.LComment
		}

		lineitem := Lineitem{
			LOrderkey:      oOrderkey,
			LLinenumber:    payload.LLinenumber,
			LExtendedprice: payload.LExtendedprice,
			LDiscount:      payload.LDiscount,
			LTax:           payload.LTax,
			LShipdate:      payload.LShipdate,
			LComment:       comment,
		}

		if err := tx.Table("lineitem").Create(&lineitem).Error; err != nil {
			tx.Rollback()
			return err
		}

		if err := tx.Commit().Error; err != nil {
			return err
		}

		return c.Status(201).JSON(fiber.Map{
			"l_orderkey":   oOrderkey,
			"l_linenumber": payload.LLinenumber,
		})
	})

	app.Post("/api/orders", func(c *fiber.Ctx) error {
		payload := CreateOrderPayload{}
		if err := c.BodyParser(&payload); err != nil {
			payload = CreateOrderPayload{}
		}

		tx := db.Begin()
		if tx.Error != nil {
			return tx.Error
		}

		orderStatus := "O"
		if payload.OOrderstatus != nil {
			orderStatus = *payload.OOrderstatus
		}

		comment := ""
		if payload.OComment != nil {
			comment = *payload.OComment
		}

		order := Order{
			OOrderstatus: orderStatus,
			OTotalprice:  0,
			OOrderdate:   payload.OOrderdate,
			OComment:     comment,
		}

		if err := tx.Table("orders").Create(&order).Error; err != nil {
			tx.Rollback()
			return err
		}

		oOrderkey := order.OOrderkey

		for _, item := range payload.Lineitems {
			itemComment := ""
			if item.LComment != nil {
				itemComment = *item.LComment
			}

			lineitem := Lineitem{
				LOrderkey:      oOrderkey,
				LLinenumber:    item.LLinenumber,
				LExtendedprice: item.LExtendedprice,
				LDiscount:      item.LDiscount,
				LTax:           item.LTax,
				LShipdate:      item.LShipdate,
				LComment:       itemComment,
			}

			if err := tx.Table("lineitem").Create(&lineitem).Error; err != nil {
				tx.Rollback()
				return err
			}
		}

		var totalRow struct {
			Total float64 `gorm:"column:total"`
		}
		if err := tx.Raw(
			"SELECT COALESCE(SUM(l_extendedprice * (1 - l_discount) * (1 + l_tax)), 0) AS total FROM lineitem WHERE l_orderkey = ?",
			oOrderkey,
		).Scan(&totalRow).Error; err != nil {
			tx.Rollback()
			return err
		}

		if err := tx.Table("orders").Where("o_orderkey = ?", oOrderkey).Update("o_totalprice", totalRow.Total).Error; err != nil {
			tx.Rollback()
			return err
		}

		if err := tx.Commit().Error; err != nil {
			return err
		}

		return c.Status(201).JSON(fiber.Map{
			"o_orderkey":   oOrderkey,
			"o_totalprice": totalRow.Total,
		})
	})

	port := os.Getenv("PORT")
	if port == "" {
		port = "5000"
	}

	log.Fatal(app.Listen("0.0.0.0:" + port))
}

package main

import (
	"database/sql"
	"os"
	"strconv"

	"github.com/gofiber/fiber/v2"
	_ "modernc.org/sqlite"
)

var db *sql.DB

func getDB() *sql.DB {
	return db
}

func closeDB() {
	if db != nil {
		_ = db.Close()
	}
}

func getOrder(c *fiber.Ctx) error {
	oOrderkey, err := strconv.Atoi(c.Params("o_orderkey"))
	if err != nil {
		return c.Status(404).JSON(fiber.Map{"error": "Order not found"})
	}

	db := getDB()
	row := db.QueryRow(
		"SELECT o_orderkey, o_orderstatus, o_totalprice, o_orderdate, o_comment "+
			"FROM orders WHERE o_orderkey = ?",
		oOrderkey,
	)

	var orderkey int
	var orderstatus string
	var totalprice float64
	var orderdate string
	var comment sql.NullString

	err = row.Scan(&orderkey, &orderstatus, &totalprice, &orderdate, &comment)
	if err == sql.ErrNoRows {
		return c.Status(404).JSON(fiber.Map{"error": "Order not found"})
	}
	if err != nil {
		return err
	}

	var commentVal interface{}
	if comment.Valid {
		commentVal = comment.String
	} else {
		commentVal = nil
	}

	return c.Status(200).JSON(fiber.Map{
		"o_orderkey":    orderkey,
		"o_orderstatus": orderstatus,
		"o_totalprice":  totalprice,
		"o_orderdate":   orderdate,
		"o_comment":     commentVal,
	})
}

func addLineitem(c *fiber.Ctx) error {
	oOrderkey, err := strconv.Atoi(c.Params("o_orderkey"))
	if err != nil {
		return c.Status(404).JSON(fiber.Map{"error": "Order not found"})
	}

	payload := map[string]interface{}{}
	_ = c.BodyParser(&payload)

	db := getDB()
	tx, err := db.Begin()
	if err != nil {
		return err
	}

	row := tx.QueryRow(
		"SELECT o_orderkey FROM orders WHERE o_orderkey = ?",
		oOrderkey,
	)
	var existingOrderkey int
	err = row.Scan(&existingOrderkey)
	if err == sql.ErrNoRows {
		_ = tx.Rollback()
		return c.Status(404).JSON(fiber.Map{"error": "Order not found"})
	}
	if err != nil {
		_ = tx.Rollback()
		return err
	}

	_, err = tx.Exec(
		"INSERT INTO lineitem (l_orderkey, l_linenumber, l_extendedprice, l_discount, l_tax, l_shipdate, l_comment) "+
			"VALUES (?, ?, ?, ?, ?, ?, ?)",
		oOrderkey,
		payload["l_linenumber"],
		payload["l_extendedprice"],
		payload["l_discount"],
		payload["l_tax"],
		payload["l_shipdate"],
		func() interface{} {
			if v, ok := payload["l_comment"]; ok {
				return v
			}
			return ""
		}(),
	)
	if err != nil {
		_ = tx.Rollback()
		return err
	}

	if err := tx.Commit(); err != nil {
		return err
	}

	return c.Status(201).JSON(fiber.Map{
		"l_orderkey":   oOrderkey,
		"l_linenumber": payload["l_linenumber"],
	})
}

func createOrder(c *fiber.Ctx) error {
	payload := map[string]interface{}{}
	_ = c.BodyParser(&payload)

	db := getDB()
	tx, err := db.Begin()
	if err != nil {
		return err
	}

	res, err := tx.Exec(
		"INSERT INTO orders (o_orderstatus, o_totalprice, o_orderdate, o_comment) "+
			"VALUES (?, 0, ?, ?)",
		func() interface{} {
			if v, ok := payload["o_orderstatus"]; ok {
				return v
			}
			return "O"
		}(),
		payload["o_orderdate"],
		func() interface{} {
			if v, ok := payload["o_comment"]; ok {
				return v
			}
			return ""
		}(),
	)
	if err != nil {
		_ = tx.Rollback()
		return err
	}

	oOrderkey64, err := res.LastInsertId()
	if err != nil {
		_ = tx.Rollback()
		return err
	}
	oOrderkey := int(oOrderkey64)

	lineitemsRaw := payload["lineitems"].([]interface{})
	for _, itemRaw := range lineitemsRaw {
		item := itemRaw.(map[string]interface{})
		_, err = tx.Exec(
			"INSERT INTO lineitem (l_orderkey, l_linenumber, l_extendedprice, "+
				"l_discount, l_tax, l_shipdate, l_comment) "+
				"VALUES (?, ?, ?, ?, ?, ?, ?)",
			oOrderkey,
			item["l_linenumber"],
			item["l_extendedprice"],
			item["l_discount"],
			item["l_tax"],
			item["l_shipdate"],
			func() interface{} {
				if v, ok := item["l_comment"]; ok {
					return v
				}
				return ""
			}(),
		)
		if err != nil {
			_ = tx.Rollback()
			return err
		}
	}

	row := tx.QueryRow(
		"SELECT COALESCE(SUM(l_extendedprice * (1 - l_discount) * (1 + l_tax)), 0) AS total "+
			"FROM lineitem WHERE l_orderkey = ?",
		oOrderkey,
	)
	var total float64
	if err := row.Scan(&total); err != nil {
		_ = tx.Rollback()
		return err
	}

	_, err = tx.Exec(
		"UPDATE orders SET o_totalprice = ? WHERE o_orderkey = ?",
		total, oOrderkey,
	)
	if err != nil {
		_ = tx.Rollback()
		return err
	}

	if err := tx.Commit(); err != nil {
		return err
	}

	return c.Status(201).JSON(fiber.Map{
		"o_orderkey":   oOrderkey,
		"o_totalprice": total,
	})
}

func main() {
	database := os.Getenv("DB_PATH")
	if database == "" {
		database = "app.db"
	}

	var err error
	db, err = sql.Open("sqlite", database)
	if err != nil {
		panic(err)
	}
	defer closeDB()

	app := fiber.New()

	app.Get("/api/orders/:o_orderkey<int>", getOrder)
	app.Post("/api/orders/:o_orderkey<int>/lineitems", addLineitem)
	app.Post("/api/orders", createOrder)

	port := os.Getenv("PORT")
	if port == "" {
		port = "5000"
	}

	if err := app.Listen("0.0.0.0:" + port); err != nil {
		panic(err)
	}
}

package main

import (
	"database/sql"
	"errors"
	"net/http"
	"os"
	"strconv"

	"github.com/gin-gonic/gin"
	"gorm.io/driver/sqlite"
	"gorm.io/gorm"
)

type Order struct {
	OOrderkey    int64   `gorm:"column:o_orderkey;primaryKey;autoIncrement" json:"o_orderkey"`
	OOrderstatus string  `gorm:"column:o_orderstatus" json:"o_orderstatus"`
	OTotalprice  float64 `gorm:"column:o_totalprice" json:"o_totalprice"`
	OOrderdate   string  `gorm:"column:o_orderdate" json:"o_orderdate"`
	OComment     string  `gorm:"column:o_comment" json:"o_comment"`
}

func (Order) TableName() string {
	return "orders"
}

type Lineitem struct {
	LOrderkey      int64    `gorm:"column:l_orderkey;primaryKey" json:"l_orderkey"`
	LLinenumber    int      `gorm:"column:l_linenumber;primaryKey" json:"l_linenumber"`
	LExtendedprice float64  `gorm:"column:l_extendedprice" json:"l_extendedprice"`
	LDiscount      float64  `gorm:"column:l_discount" json:"l_discount"`
	LTax           float64  `gorm:"column:l_tax" json:"l_tax"`
	LShipdate      *string  `gorm:"column:l_shipdate" json:"l_shipdate"`
	LComment       string   `gorm:"column:l_comment" json:"l_comment"`
}

func (Lineitem) TableName() string {
	return "lineitem"
}

type AddLineitemPayload struct {
	LLinenumber    int      `json:"l_linenumber"`
	LExtendedprice float64  `json:"l_extendedprice"`
	LDiscount      float64  `json:"l_discount"`
	LTax           float64  `json:"l_tax"`
	LShipdate      *string  `json:"l_shipdate"`
	LComment       *string  `json:"l_comment"`
}

type CreateOrderLineitemPayload struct {
	LLinenumber    int      `json:"l_linenumber"`
	LExtendedprice float64  `json:"l_extendedprice"`
	LDiscount      float64  `json:"l_discount"`
	LTax           float64  `json:"l_tax"`
	LShipdate      *string  `json:"l_shipdate"`
	LComment       *string  `json:"l_comment"`
}

type CreateOrderPayload struct {
	OOrderstatus *string                      `json:"o_orderstatus"`
	OOrderdate   string                       `json:"o_orderdate"`
	OComment     *string                      `json:"o_comment"`
	Lineitems    []CreateOrderLineitemPayload `json:"lineitems"`
}

func main() {
	database := os.Getenv("DB_PATH")
	if database == "" {
		database = "app.db"
	}

	db, err := gorm.Open(sqlite.Open(database), &gorm.Config{})
	if err != nil {
		panic(err)
	}

	sqlDB, err := db.DB()
	if err != nil {
		panic(err)
	}
	defer sqlDB.Close()

	r := gin.Default()

	r.GET("/api/orders/:o_orderkey", func(c *gin.Context) {
		oOrderkey, err := strconv.ParseInt(c.Param("o_orderkey"), 10, 64)
		if err != nil {
			c.JSON(http.StatusNotFound, gin.H{"error": "Order not found"})
			return
		}

		var result struct {
			OOrderkey    int64   `json:"o_orderkey"`
			OOrderstatus string  `json:"o_orderstatus"`
			OTotalprice  float64 `json:"o_totalprice"`
			OOrderdate   string  `json:"o_orderdate"`
			OComment     string  `json:"o_comment"`
		}

		tx := db.Raw(
			"SELECT o_orderkey, o_orderstatus, o_totalprice, o_orderdate, o_comment FROM orders WHERE o_orderkey = ?",
			oOrderkey,
		).Scan(&result)

		if tx.Error != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": tx.Error.Error()})
			return
		}
		if tx.RowsAffected == 0 {
			c.JSON(http.StatusNotFound, gin.H{"error": "Order not found"})
			return
		}

		c.JSON(http.StatusOK, result)
	})

	r.POST("/api/orders/:o_orderkey/lineitems", func(c *gin.Context) {
		oOrderkey, err := strconv.ParseInt(c.Param("o_orderkey"), 10, 64)
		if err != nil {
			c.JSON(http.StatusNotFound, gin.H{"error": "Order not found"})
			return
		}

		var payload AddLineitemPayload
		if err := c.ShouldBindJSON(&payload); err != nil {
			payload = AddLineitemPayload{}
		}

		err = db.Transaction(func(tx *gorm.DB) error {
			var order struct {
				OOrderkey int64 `gorm:"column:o_orderkey"`
			}

			check := tx.Raw(
				"SELECT o_orderkey FROM orders WHERE o_orderkey = ?",
				oOrderkey,
			).Scan(&order)
			if check.Error != nil {
				return check.Error
			}
			if check.RowsAffected == 0 {
				return sql.ErrNoRows
			}

			comment := ""
			if payload.LComment != nil {
				comment = *payload.LComment
			}

			insert := tx.Exec(
				"INSERT INTO lineitem (l_orderkey, l_linenumber, l_extendedprice, l_discount, l_tax, l_shipdate, l_comment) VALUES (?, ?, ?, ?, ?, ?, ?)",
				oOrderkey, payload.LLinenumber, payload.LExtendedprice,
				payload.LDiscount, payload.LTax,
				payload.LShipdate, comment,
			)
			return insert.Error
		})

		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				c.JSON(http.StatusNotFound, gin.H{"error": "Order not found"})
				return
			}
			c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
			return
		}

		c.JSON(http.StatusCreated, gin.H{"l_orderkey": oOrderkey, "l_linenumber": payload.LLinenumber})
	})

	r.POST("/api/orders", func(c *gin.Context) {
		var payload CreateOrderPayload
		if err := c.ShouldBindJSON(&payload); err != nil {
			payload = CreateOrderPayload{}
		}

		var oOrderkey int64
		var total float64

		err := db.Transaction(func	tx *gorm.DB) error {
			orderStatus := "O"
			if payload.OOrderstatus != nil {
				orderStatus = *payload.OOrderstatus
			}

			comment := ""
			if payload.OComment != nil {
				comment = *payload.OComment
			}

			insertOrder := tx.Exec(
				"INSERT INTO orders (o_orderstatus, o_totalprice, o_orderdate, o_comment) VALUES (?, 0, ?, ?)",
				orderStatus, payload.OOrderdate, comment,
			)
			if insertOrder.Error != nil {
				return insertOrder.Error
			}

			var rowID int64
			if err := tx.Raw("SELECT last_insert_rowid()").Scan(&rowID).Error; err != nil {
				return err
			}
			oOrderkey = rowID

			for _, item := range payload.Lineitems {
				itemComment := ""
				if item.LComment != nil {
					itemComment = *item.LComment
				}

				insertItem := tx.Exec(
					"INSERT INTO lineitem (l_orderkey, l_linenumber, l_extendedprice, l_discount, l_tax, l_shipdate, l_comment) VALUES (?, ?, ?, ?, ?, ?, ?)",
					oOrderkey, item.LLinenumber, item.LExtendedprice,
					item.LDiscount, item.LTax,
					item.LShipdate, itemComment,
				)
				if insertItem.Error != nil {
					return insertItem.Error
				}
			}

			var totalRow struct {
				Total float64 `gorm:"column:total"`
			}
			sumQuery := tx.Raw(
				"SELECT COALESCE(SUM(l_extendedprice * (1 - l_discount) * (1 + l_tax)), 0) AS total FROM lineitem WHERE l_orderkey = ?",
				oOrderkey,
			).Scan(&totalRow)
			if sumQuery.Error != nil {
				return sumQuery.Error
			}
			total = totalRow.Total

			updateOrder := tx.Exec(
				"UPDATE orders SET o_totalprice = ? WHERE o_orderkey = ?",
				total, oOrderkey,
			)
			return updateOrder.Error
		})

		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
			return
		}

		c.JSON(http.StatusCreated, gin.H{"o_orderkey": oOrderkey, "o_totalprice": total})
	})

	port := os.Getenv("PORT")
	if port == "" {
		port = "5000"
	}

	if err := r.Run("0.0.0.0:" + port); err != nil {
		panic(err)
	}
}

