			Select("o_orderkey, o_totalprice, o_orderdate, o_latest_shipdate, o_comment").
			Where("o_orderkey = ?", oOrderkey).
			Take(&row)

		if tx.Error != nil {
			if tx.Error == gorm.ErrRecordNotFound {
				c.JSON(http.StatusNotFound, gin.H{"error": "Order not found"})
